-- GENERATED by benchmarks/tpch/scripts/qualify_queries.py from ../queries — do not edit.
-- Mixed layout: dimensions in postgresql.tpch_mixed, facts in hive.tpch.
-- TPC-H Q5: Local Supplier Volume
SELECT
    n_name,
    SUM(l_extendedprice)
FROM postgresql.tpch_mixed.customer
JOIN hive.tpch.orders ON c_custkey = o_custkey
JOIN hive.tpch.lineitem ON l_orderkey = o_orderkey
JOIN postgresql.tpch_mixed.supplier ON l_suppkey = s_suppkey
JOIN postgresql.tpch_mixed.nation ON s_nationkey = n_nationkey
JOIN postgresql.tpch_mixed.region ON n_regionkey = r_regionkey
WHERE r_name = 'ASIA'
    AND o_orderdate >= DATE '1994-01-01'
    AND o_orderdate < DATE '1995-01-01'
GROUP BY n_name
ORDER BY SUM(l_extendedprice) DESC
